use vstd::prelude::*;

verus! {
    /// Returns the index of the first odd element in `v`.
    /// 
    /// Requires that `v` contains at least one odd element,
    /// and ensures that the returned index is the smallest index
    /// at which an odd element appears.
    fn choose_odd(v: &Vec<u64>) -> (idx: usize)
        requires
            // There is at least one odd element in v
            exists |i: usize| i < v.len() && v[i] % 2 == 1,
        ensures
            // The result is a valid index
            idx < v.len(),
            // v[idx] is odd
            v[idx] % 2 == 1,
            // All earlier positions are even
            forall |j: usize| j < idx ==> v[j] % 2 == 0,
    {
        // Since we required that there is an odd element,
        // position(...).unwrap() will not panic.
        v.iter()
         .position(|&x| x & 1 == 1)
         .unwrap()
    }
}

